%[text] %[text:anchor:T_EF5120B5] # Spike Artifacts
%[text] Investigate how tACS stimulation artifacts affect spike recordings.
%[text:tableOfContents]{"heading":"Table of Contents"}
%%
%[text] %[text:anchor:H_9BC26763] ## Setup Simulation
%[text] Simulation parameters
run('../startup'); % Make sure all toolboxes are on the path
defaults= [];
defaults.duration                  = 120;    % 2 min
defaults.stimulatorSamplingRate    = 1e3;     % e.g., Starstim (1 kHz)
defaults.currentResolution         = 1e-6;    % 1 muA
defaults.resistance                = 1;        % 1 mA -> 1 mV artifact
defaults.recordingSamplingRate     = 30e3;     % 30kHz
defaults.amplifierLinearRange      = 6.8e-3;   % Linear range of amplified 6.8 mV
defaults.amplifierGain             = 20;       % Amplify 20x
defaults.adcNonlinearity           = 100;      % Piecewise linear
defaults.adcRange                  = 10e-3;     % Input range of the ADC.
defaults.adcBitDepth               = 16;       % Number of bits in the AD convertor
defaults.highPass                  = 0.01;     % High pass filter on the preamp. 
defaults.reproducible              = 2;       % Seed the RNG to get reproducible results

defaults.tacsAmplitude     = 120e-6;    % 120 muA
defaults.tacsFrequency     = 40;
defaults.tacsPhaseOffset   = 0.5*pi;
%[text] Define the common neural signals
defaults.spikePeak                 = 60e-6;   % 60 muV
defaults.spikeRate                 = 100;      % 100 spk/s
defaults.poisson                   = true;     % Poisson spiking
defaults.fixNrSpikes               = true;     % Deviate from Poisson to get exact firing rate.
defaults.refractoryPeriod          = 1.5e-3;   % 1.5 ms
defaults.additive                  = 20e-6;    % Background activity/noise
defaults.pinkNoise                 = true;     % Pink background noise
defaults.synchrony                 = 0;        % Poisson random spikes, no relation with LFP
defaults.lfpAmplitude              = 0;        % No intrinsic oscillation
defaults.multiplicative            = 0;        % No multiplicative noise

%[text] Define the common parameters for artifact removal
ar = [];
ar.recordingSamplingRate = defaults.recordingSamplingRate; % Match to the recording
ar.segmentDuration       = 3;
ar.tacsFrequency         = defaults.tacsFrequency;
%[text] Setup the parameters for the artifact removal algorithms to explore.

fastr = [];
fastr.name = "FASTR";
fastr.options.slack = 5e-3;
fastr.options.nrSegsPerWindow = 10;
fastr.options.pcaNr = 2;
fastr.options.pcaVarExplained = Inf;
fastr.options.pcaNrSegsPerWindow = Inf;
fastr.options.referenceSegment = 1;

rbar = [];
rbar.name = "RBAR";
rbar.options = [];

nop = [    ];
nop.name = "NOP";

%[text] Define the filter that extract signals in the "spike band":
lowCut                      = 500;  % high pass filter cut off
highCut                     = 7000; % Low pass filter cut off.
filterOrder                 = 3; % Filter order  (Butterworth)
%%
%[text] ## Stimulator Discretization Artifacts
%[text] With typical tACS frequencies below 100 Hz and typical spiking signals near 1 kHz, one might expect that a simple high-pass filter would remove all tACS artifacts from the signal used for spike-based analysis. This is indeed the case for an ideal stimulator that genreates sinusoidal waveforms with high temporal resolution. Stimulators, however, typically use a sampled D2A converter to generate currents and such sampled sinusoids can generate artifacts in the spike band. 
%[text] To illustrate this I simulated a stimulator with a 1 kHz sampling rate, and 1 muA current resolution and a  1mA tACS artifact.
A                   = artSim(defaults);
A.sim;
%[text] The simulation has now created the `vTcsActual` - the voltage artifact created by this stimulator. 
%[text] Visualizing just two cycles of the waveform illustrates the problem: 
[~,axs] = fig('Name','Fig8','paperCols',2,'height',9,'nrRows',2,'nrCols',3,'byColumn',false); %[output:5dc4ecdc]
%[text] Show the voltage artifact
nrCyclesToShow = 2;
axes(axs(1,1)) %[output:5dc4ecdc]
plot(A.tSimulate/1e-3,A.vTcsActual/1e-3) %[output:5dc4ecdc]
xl = [0 nrCyclesToShow/A.tacsFrequency/1e-3];
xlim (xl); %[output:5dc4ecdc]
xlabel 'Time (ms)' %[output:5dc4ecdc]
ylabel 'Voltage (mV)' %[output:5dc4ecdc]
axs(1).XTick = xl; %[output:5dc4ecdc]

%[text] and its amplitude spectrum
axes(axs(1,2)) %[output:5dc4ecdc]
[ft,frequency]= fftReal(A.vTcsActual(:),A.quasiContinuousSamplingRate);
amplitude =abs(ft)./(2*numel(A.vTcsActual));

plot(frequency/1e3,amplitude/1e-6); %[output:5dc4ecdc]
xlabel 'Frequency (kHz)' %[output:5dc4ecdc]
ylabel 'Amplitude (\muV)' %[output:5dc4ecdc]
xlim([lowCut highCut]/1e3) %[output:5dc4ecdc]
%[text] The spectral power shows that the artifact is not stationary, but varies with tACS phase
axes(axs(1,3)) %[output:5dc4ecdc]
% Spectrogram
boundaryCycles =4;
samplesPerCycle = A.quasiContinuousSamplingRate./A.tacsFrequency;
keep = 1:round(nrCyclesToShow*samplesPerCycle)+boundaryCycles*samplesPerCycle;
x = A.vTcsActual(keep);
[powerSpectrum,frequency,time] = pspectrum(x,A.quasiContinuousSamplingRate,'spectrogram', ...
    'FrequencyResolution',500,'FrequencyLimits',[lowCut highCut]);
amplitude = 1e6*sqrt(2)*sqrt(powerSpectrum); % Peak amplitude in microvolts.
imagesc(time*1e3,frequency/1e3,amplitude); % ms, kHz, muV %[output:5dc4ecdc]
axis xy %[output:5dc4ecdc]
colorbar %[output:5dc4ecdc]
ylabel('Frequency (kHz)') %[output:5dc4ecdc]
xlabel('Time (s)') %[output:5dc4ecdc]
clim([0 prctile(amplitude(:),99)]) %[output:5dc4ecdc]

xlim([75 100]) %[output:5dc4ecdc]
axs(3).XTick =[75 100]; %[output:5dc4ecdc]
axs(3).YTick =[lowCut/1e3 1:highCut/1e3]; %[output:5dc4ecdc]
axs(3).XTickLabel = {'0','25'}; %[output:5dc4ecdc]
ylim([lowCut highCut]/1e3) %[output:5dc4ecdc]
h = colorbar; %[output:5dc4ecdc]
ylabel(h,'\muV') %[output:5dc4ecdc]
title '' %[output:5dc4ecdc]
colormap hot %[output:5dc4ecdc]
%[text] Add a polar representation of the peak of the artifact to illustrate the phase dependence
trgPos = get(axs(2,1),'Position');
trgPos([1 2]) = trgPos([1 2]).*[0.7 0.9];
pax = polaraxes('Position',trgPos); %[output:5dc4ecdc]
axes(pax); %[output:5dc4ecdc]
[P,F,T] = pspectrum(x,A.quasiContinuousSamplingRate,'spectrogram','FrequencyResolution',500,'FrequencyLimits',[0 highCut]);
oneCycle =T>=3/A.tacsFrequency & T< 4/A.tacsFrequency;

P =sum(P(:,oneCycle)); % Sum one cycle over the spike band
phase = A.tacsPhaseOffset+ linspace(0,2*pi*(1-1/numel(P)),numel(P)+1);
P = [P P(1)];
polarplot(phase,P) %[output:5dc4ecdc]

pax.RTick = []; %[output:5dc4ecdc]
pax.ThetaTick = [0 90 180 270]; %[output:5dc4ecdc]
pax.Color = 'w';
delete(axs(2,1)) %[output:5dc4ecdc]

%[text] And illustrate that the power in the spike band increases (linearly) with the tACS frequency
tacsFreqs                    = [2 5 10 20 40];
nrTacsFreqs                  = numel(tacsFreqs);
artifactPower = nan(nrTacsFreqs,1);
for i = 1:nrTacsFreqs
    A.tacsFrequency             =tacsFreqs(i);
    A.reset;
    A.simTCS;
    [ft,frequency]= fftReal(A.vTcsActual(:),A.quasiContinuousSamplingRate);
    % Remove the power that would be filtered out
    ft(frequency < lowCut | frequency > highCut) = 0;
    signal = ifftReal(ft,frequency,A.quasiContinuousSamplingRate);
    artifactPower(i) = max(abs(signal));
end
axes(axs(2,2)) %[output:5dc4ecdc]
plot(tacsFreqs,artifactPower./1e-6) %[output:5dc4ecdc]
xlabel 'tACS Frequency (Hz)' %[output:5dc4ecdc]
ylabel 'Artifact (\muV)' %[output:5dc4ecdc]
%[text] Finally, show the shape of the artifact at selected tACS phases.

samplesPerCycle = A.quasiContinuousSamplingRate./A.tacsFrequency;
axes(axs(2,3)) %[output:5dc4ecdc]
% Bandpass filter to take only the signal in the spike band
[b,a] = butter(filterOrder,[lowCut highCut]/(A.quasiContinuousSamplingRate/2),'bandpass');
filteredVoltage   = filtfilt(b,a,A.vTcsActual(:));
% Select a time window similar to a spike 
samplesToShow     = 1e-3*A.quasiContinuousSamplingRate; %  1 ms
samplesBefore     = round(0.5*samplesToShow);
samplesAfter      = samplesToShow-samplesBefore;
phase             = [0 90 180 270];
offset            = round(samplesPerCycle*(rad2deg(2*pi-A.tacsPhaseOffset)/360));
t                 = (-samplesBefore:samplesAfter)/A.quasiContinuousSamplingRate;
for ph=phase
    ix = offset+ round(samplesPerCycle*ph/360) + (-samplesBefore:samplesAfter);
    plot(t/1e-3,filteredVoltage(ix)/1e-6); %[output:5dc4ecdc]
    hold on
end
xlabel 'Time (ms)' %[output:5dc4ecdc]
ylabel 'Votlage (\muV)' %[output:5dc4ecdc]
legend(string(num2str(phase')) + "^\circ","Position", [0.74 0.31 0.12, 0.14]) %[output:5dc4ecdc]
legend('boxoff') %[output:5dc4ecdc]
%%
%[text] %[text:anchor:H_1C3B008F] ## Spike Sorting 
%[text] Spike sorting labels spikes as belonging to a specific neuron and is often used to focus analysis on one (or more) identified neurons with recognizable wave forms. This process is standard, but in the context of stimulation artifacts, there is a potential that the spike sorting procedure masks (rather than removes) the effects of stimulation. These simulations explore that using the UMS2K spike sorter (although the details of spike sorting are unlikely to change the overall message).
%[text] Define the neural signals:
A = artSim(defaults);
A.sim; 
%[text] In most approaches, the spike detection threshold is defined relative to some noise level that is estimated from the signal in the spike band. The simulations generate one trial with tACS and one trial without tACS (but the same spikes). By setting `sharedThreshold` to `true, the v`oltage threshold is estimated from the concatenated signals in the spike band (i.e., with and without tACS).  Note that this creates an interaction between spike detection in trials with and without tACS. Notably, if tACS generates large artifacts in the spike band, the voltage threshold will be high and true spikes -even in trials without stimulation -  could be lost  resulting in false negatives even in sham trials. 
%[text] The spike detection can be changed to use a separate threshold for stimulated and non-stimulated trials (`sharedThreshold = false`) - although this creates its own issues in the interpretation of the results.
threshold                      = 3.5 ; % Spikes are defined as this many standard deviations above zero.
sharedThreshold                = true;
%[text] After spike detection, UMS2K extracts a waveform for each spike to determine clusters based on the waveform shape. (This too leads to an interaction between tACS contaminated and tACS-free spikes).
nrPre                           = 1e-3*A.recordingSamplingRate; % Samples to keep before threshold crossing
nrPost                          = nrPre; % Samples to keep after threshold crossing
%[text] ArtSim can use different methods to do spike sorting. ALL  means no spike sorting; it returns all threshold crossings. In MATCHSHAM mode, spikes in the tACS trial are compared to the clusters found in the no-tACS trial and assigned to the best-matching cluster. MOSTSPIKES keeps only the unit with the most spikes. Investigate spike detection first:
spikeSortingMode                ="ALL";
%[text] Run the simulation to illustrate the problem caused by stimulation artifacts in a pipeline that only filters to the spike band (i.e. without other artifact removal). 
[~,axs] = fig('Name',"Fig9",'paperCols',2,'height',12,'nrRows',2,'nrCols',2,'byColumn',false);    %[output:0fc211c1]
args = namedargs2cell(ar);
arResults= artifactRemoval(A.vContaminated,nop, args{:},groundTruth=A.vTruth); %[output:53ec52af]
sortResultsNopAll  = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = sharedThreshold, spikeSortingMode=spikeSortingMode,axs=[axs(1:2) gobjects(1,2)],nrBootstrap=100); %[output:5ffacb5c] %[output:0fc211c1]
%[text] This figure shows the voltage trace filtered to the spike band (red), the ground truth spikes (circle), and the detected spikes (asterisk) for a snippet from the no-tACS trial (a) and the tACS trial (b). Panel c shows a polar histogram of the spikes as a function of the phase of tACS.  In the sham trial all phases are equally likely, in the tACS trial, the 0 and 180 degree phases are less likely to result in a detected spike. Panel d shows that the average waveform of the sorted spikes does not depend on the phase. 
%[text] The phase dependence arises due to the larger current steps near the 180 and 0 phases. Differences between 180 and 0 can occur if the spike threshold detection algorithm treates negative going deflections differently form positive deflections. 
spikeSortingMode                ="MATCHSHAM";
%[text] Run the simulation to illustrate the problem caused by stimulation artifacts in a pipeline that only filters to the spike band (i.e. without other artifact removal). 
 
arResults= artifactRemoval(A.vContaminated,nop, args{:},groundTruth=A.vTruth); %[output:6eb0b980]
sortResultsNop  = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = sharedThreshold, spikeSortingMode=spikeSortingMode,axs=[gobjects(1,2) axs(3:4)],nrBootstrap=100); %[output:164adcb1] %[output:0fc211c1]

%[text] In these simulations there are no false positive  (i.e. sorted spikes found where none were simulated), but false negatives are quite frequent; not only in the tACS trial (32%), but also in the Control/Sham trial (5%). The latter is a consequence of using a single spike threshold and spike template estimation - this results in a contamination of the spike sorting process in the sham trial.
%[text] Taken together, these stimulation show that merely filtering to the spike band is not sufficient to remove spike artifacts. 
%%
%[text] %[text:anchor:H_0F76CEFC] ### Spike Sorting with FASTR 
%[text] Run the same spike sorting pipeline now with FASTR recovery of the underlying neural signal.   
arResults= artifactRemoval(A.vContaminated,fastr, args{:},groundTruth=A.vTruth); %[output:5022c261]
sortResultsFastr  = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode); %[output:27a6048c] %[output:87367832] %[output:59754722]

%[text] This shows FASTR helps to recover true spiking. But note that some false negatives remain.  
%%
%[text] ### Spike sorting with RBAR
arResults= artifactRemoval(A.vContaminated,rbar, args{:},groundTruth=A.vTruth,vRecordTcs=A.vRecordTcs); %[output:34a69ef2]
sortResultsRbar  = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode); %[output:46b30fd2] %[output:32183866] %[output:02b122f4]

%[text] RBAR recovers the spikes; with zero false negatives.
%%
%[text] %[text:anchor:H_261845DF] ## Amplifier Saturation
%[text] Simulate what happens if spikes are pushed into the nonlinear range of the amplifier. 
A = artSim(defaults);

%[text] Set the amplifier properties to saturate slightly
A.adcNonlinearity           = 4;   % Sigmoidal
A.resistance                = 2;   % Increase the tACS artifact to get closer to saturation
A.stimulatorSamplingRate    = 1e6;  % Remove stimulator discretization artifact to focus on amp saturation
%[text] Set the tACS properties  and run simulation

A.sim;
args = namedargs2cell(ar);
spikeSortingMode              = "ALL";

[~,axs] = fig('Name',"Fig11",'paperCols',1.5,'height',4,'nrRows',1,'nrCols',2,'byColumn',true); %[output:729d560a]
arResults= artifactRemoval(A.vContaminated,rbar, args{:},groundTruth=A.vTruth,vRecordTcs=A.vRecordTcs); %[output:287c890c]
sortResultsRBARNonLin  = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=[gobjects(1,2) axs]); %[output:5d873777] %[output:729d560a]

%[text] Show the saturation (illustrating that it can be subtle)
[~,axs] = fig('Name',"Fig10",'paperCols',1.5,'height',4, ... %[output:7f790356]
    'nrRows',1,'nrCols',2); %[output:7f790356]

% Transfer curve: amplifier input and output are both in the left panel.
axes(axs(1)) %[output:7f790356]
inputRange = A.adcRange/A.amplifierGain;
in = linspace(-inputRange,inputRange,100);
[out,satPoint] = adc(A,in,satLevel = 95,isTimeSeries= false);
plot(in/1e-3,out/1e-3,'LineWidth',1.2) %[output:7f790356]
hold on %[output:7f790356]
plot(in/1e-3,A.amplifierGain*in/1e-3,'LineStyle',':') %[output:7f790356]
xline([-satPoint satPoint]/1e-3,'k:') %[output:7f790356]

xlabel 'Neural signal(mV)' %[output:7f790356]
ylabel 'ADC output (mV)' %[output:7f790356]
legend('Amplifier output','Linear gain') %[output:7f790356]
title(sprintf('Gain = %g, range = %g mV', ... %[output:7f790356]
    A.amplifierGain,A.amplifierLinearRange/1e-3)) %[output:7f790356]


% Histogram: A.vContaminated is already the recorded, post-ADC signal.
axes(axs(2)) %[output:7f790356]
recordedSamples = A.vContaminated(:);
binEdges = linspace(-A.adcRange,A.adcRange,41);
[sampleCount,binEdges] = histcounts(recordedSamples,binEdges);
binCenters = (binEdges(1:end-1)+binEdges(2:end))/2;
bar(binCenters/1e-3,sampleCount,'hist') %[output:7f790356]
hold on %[output:7f790356]
% Both ADC and preamp limits are output-referred, so the smaller one is the true total
% saturation level of the acquisition chain.
saturation = min(A.amplifierLinearRange,A.adcRange);
headroom  = saturation- max(recordedSamples);
nearSaturation = abs(recordedSamples) >= 0.99*saturation;
nearSaturationPercent = 100*mean(nearSaturation);
xline([-A.adcRange A.adcRange]/1e-3,'r:') %[output:7f790356]
xline([-saturation saturation]/1e-3,'k:') %[output:7f790356]
xlabel 'Recorded voltage (mV)' %[output:7f790356]
ylabel 'Number of samples' %[output:7f790356]
title(sprintf('%.2f%% within 1%% of total saturation.\n Headroom: %.2f mV', nearSaturationPercent,headroom/1e-3)); %[output:7f790356]
xlim([-A.adcRange A.adcRange]/1e-3) %[output:7f790356]

%%
